import { queryOptions, useQuery } from "@tanstack/react-query";

export interface CatalogItem {
  id: string;
  name: string;
  price: number;
}

export interface CatalogFilters {
  category?: string;
  search?: string;
}

export const catalogQueryKeys = {
  all: ["catalog"] as const,
  list: (filters: CatalogFilters) => [...catalogQueryKeys.all, "list", filters] as const,
};

async function fetchCatalog(filters: CatalogFilters): Promise<CatalogItem[]> {
  const params = new URLSearchParams();
  if (filters.category !== undefined) {
    params.set("category", filters.category);
  }
  if (filters.search !== undefined) {
    params.set("search", filters.search);
  }
  const response = await fetch(`/api/catalog?${params.toString()}`);
  if (!response.ok) {
    throw new Error(`Failed to fetch catalog: ${response.status}`);
  }
  return response.json() as Promise<CatalogItem[]>;
}

export function catalogQueryOptions(filters: CatalogFilters = {}) {
  return queryOptions({
    queryKey: catalogQueryKeys.list(filters),
    queryFn: () => fetchCatalog(filters),
  });
}

export function useCatalogQuery(filters: CatalogFilters = {}) {
  return useQuery(catalogQueryOptions(filters));
}

